def hash_name(name, size):
    total = 0
    for ch in name.lower():
        if ch.isalpha():
            total += ord(ch) - ord('a') + 1
    return total % size

def prob_at_least(rolls, target, k):
    if not rolls:
        return 0.0
    successes = 0
    for trial in rolls:
        matched = 0
        for face in trial:
            if face == target:
                matched += 1
        if matched >= k:
            successes += 1
    return successes / len(rolls)

